"""

# Mapping of service class → repository / entity / DTO names
SERVICE_MAP = {
    "EventService": dict(repository="EventRepository", entity="EventModel",
                         createRequest="CreateEventRequest", updateRequest="UpdateEventRequest",
                         response="EventResponse", notFoundException="EventNotFoundException"),
    "EventExpenseService": dict(repository="EventExpenseRepository", entity="EventExpenseModel",
                                createRequest="CreateEventExpenseRequest",
                                updateRequest="UpdateEventExpenseRequest",
                                response="EventExpenseResponse",
                                notFoundException="EventExpenseNotFoundException"),
    "UtilityExpenseService": dict(repository="UtilityExpenseRepository", entity="UtilityExpenseModel",
                                  createRequest="CreateUtilityExpenseRequest",
                                  updateRequest="UpdateUtilityExpenseRequest",
                                  response="UtilityExpenseResponse",
                                  notFoundException="UtilityExpenseNotFoundException"),
    "NeighborhoodService": dict(repository="NeighborhoodRepository", entity="NeighborhoodModel",
                                createRequest="CreateNeighborhoodRequest",
                                updateRequest="UpdateNeighborhoodRequest",
                                response="NeighborhoodResponse",
                                notFoundException="NeighborhoodNotFoundException"),
    "AuthService": dict(repository="UserRepository", entity="UserModel",
                        createRequest="RegisterRequest", updateRequest="LoginRequest",
                        response="AuthResponse", notFoundException="InvalidCredentialsException"),
    "UserService": dict(repository="UserRepository", entity="UserModel",
                        createRequest="RegisterRequest", updateRequest="LoginRequest",
                        response="UserResponse", notFoundException="UserNotFoundException"),
    "VenueService": dict(repository="VenueRepository", entity="VenueModel",
                         createRequest="CreateVenueRequest", updateRequest="UpdateVenueRequest",
                         response="VenueResponse", notFoundException="VenueNotFoundException"),
}

# ---------------------------------------------------------------------------
# Generator
# ---------------------------------------------------------------------------

def render_service_test(cfg: ServiceConfig) -> str:
    m = SERVICE_MAP[cfg.service_class]
    return SERVICE_TEST_TEMPLATE.format(
        package=cfg.package,
        service=cfg.service_class,
        repository=m["repository"],
        entity=m["entity"],
        createRequest=m["createRequest"],
        updateRequest=m["updateRequest"],
        response=m["response"],
        notFoundException=m["notFoundException"],
    )

def render_controller_test(cfg: ServiceConfig) -> str:
    m = SERVICE_MAP[cfg.service_class]
    return CONTROLLER_TEST_TEMPLATE.format(
        package=cfg.package,
        controller=cfg.controller_class,
        service=cfg.service_class,
        response=m["response"],
        path=cfg.controller_path,
    )

def write_test(root: Path, cfg: ServiceConfig, kind: str, content: str, dry: bool) -> Path:
    """kind is 'service' or 'controller'"""
    test_dir = root / cfg.directory / "src" / "test" / "java" / cfg.package.replace(".", "/") / kind
    test_dir.mkdir(parents=True, exist_ok=True)
    filename = f"{cfg.service_class if kind == 'service' else cfg.controller_class}Test.java"
    path = test_dir / filename

    if dry:
        print(f"[DRY-RUN] would write {path}")
    else:
        path.write_text(content, encoding="utf-8")
        print(f"✓ wrote {path}")

    return path

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main() -> int:
    ap = argparse.ArgumentParser(description="Generate JUnit 6 tests for microservices")
    ap.add_argument("--root", required=True, help="Path to the Server/ directory")
    ap.add_argument("--dry-run", action="store_true", help="Don't write files")
    args = ap.parse_args()

    root = Path(args.root).resolve()
    if not root.is_dir():
        print(f"error: {root} is not a directory", file=sys.stderr)
        return 2

    for cfg in REGISTRY:
        service_test = render_service_test(cfg)
        write_test(root, cfg, "service", service_test, args.dry_run)

        # Some services have no controller (e.g. AuthService has AuthController,
        # which is fine; we always generate controller tests when a controller exists)
        if cfg.controller_class:
            controller_test = render_controller_test(cfg)
            write_test(root, cfg, "controller", controller_test, args.dry_run)

    print("\nDone.")
    return 0

if __name__ == "__main__":
    sys.exit(main())

