@Composable
fun ExpenseTicketItem(
    index: Int,
    modifier: Modifier = Modifier
) {
    val ticketShape = remember { TicketShape(cornerRadius = 24f, notchRadius = 20f, notchPositionXRatio = 0.80f) }
    val dividerColor = Color.Black

    Row(
        modifier = modifier
            .fillMaxWidth()
            .height(150.dp)
            .clip(ticketShape)
            .background(MaterialTheme.customColors.gray1)
    ) {
        Column(
            modifier = Modifier
                .weight(0.80f)
                .fillMaxHeight()
                .padding(16.dp),
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                BasicText(
                    text = stringResource(R.string.expenseName) + " [nombre]",
                    style = TextStyle(
                        fontSize = 22.sp,
                        fontWeight = FontWeight.SemiBold,
                        textAlign = TextAlign.Left,
                        color = MaterialTheme.customColors.gray3
                    )
                )

                BasicText(
                    text = stringResource(R.string.expenseAuthor) + " [nombre]",
                    style = TextStyle(
                        fontSize = 20.sp,
                        textAlign = TextAlign.Left,
                        color = MaterialTheme.customColors.gray3
                    )
                )
            }

            BasicText(
                text = stringResource(R.string.expenseCost) + " [valor]",
                style = TextStyle(
                    fontSize = 26.sp,
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Left,
                    color = Color.Black
                )
            )
        }

        Box(
            modifier = Modifier
                .fillMaxHeight()
                .width(1.dp)
                .drawBehind {
                    drawLine(
                        color = dividerColor,
                        start = Offset(0f, 16f),
                        end = Offset(0f, size.height - 16f),
                        pathEffect = PathEffect.dashPathEffect(floatArrayOf(10f, 10f), 0f),
                        strokeWidth = 2.dp.toPx()
                    )
                }
        )

        Column(
            modifier = Modifier
                .weight(0.20f)
                .fillMaxHeight()
                .padding(vertical = 16.dp, horizontal = 8.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(80.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                val barWeights = remember(index) {
                    listOf(2f, 1f, 3f, 1f, 4f, 2f, 1f, 3f, 2f, 1f)
                }
                barWeights.forEach { weight ->
                    Box(
                        modifier = Modifier
                            .fillMaxHeight()
                            .width(weight.dp)
                            .background(Color.Black)
                    )
                }
            }
        }
    }
}

