        val incomeColor = if (income > 0) MaterialTheme.customColors.greenText else MaterialTheme.customColors.redText
        val incomeText = buildAnnotatedString {
            append("$incomeLabel ")
            withStyle(style = SpanStyle(color = incomeColor)) {
