enum class EventTitleError { TOO_SHORT, TOO_LONG, INVALID_CHARACTERS, NONE }
enum class EventScheduleError { ENDS_BEFORE_STARTS, NONE}
enum class EventDescriptionError { NONE_AT_ALL, TOO_LONG, INVALID_CHARACTERS, NONE}
